window.botswanaCatalogueHtml=()=>`<section class="entry-section botswana-profile-catalogue"><div class="deep-dive-head"><div><div class="entry-kicker">BOTSWANA PLACE INDEX</div><h3>Regions, camps and access points</h3><p>Explore Botswana in detail after choosing it from the African atlas.</p></div><div class="bw-stat"><strong id="bwPropertyCount">${botswanaRegions.reduce((n,x)=>n+x.properties.length,0)}+</strong><span>discovery records</span></div></div><div class="bw-search"><span>⌕</span><input id="botswanaSearch" aria-label="Search Botswana places" placeholder="Search Tuli, Khwai, a lodge, reserve or activity"></div><div class="bw-region-tabs" id="botswanaTabs"></div><div class="bw-results" id="botswanaResults"></div><p class="catalogue-warning">Discovery records are not operating-status guarantees. Confirm licensing, availability, access and current trading status before booking.</p></section>`;
window.mountBotswanaCatalogue=()=>{const bwTabs=document.getElementById('botswanaTabs'),bwResults=document.getElementById('botswanaResults'),bwSearch=document.getElementById('botswanaSearch');if(!bwTabs||!bwResults||!bwSearch)return;let bwRegion='all';bwTabs.innerHTML=['All regions',...botswanaRegions.map(x=>x.region)].map((name,index)=>`<button class="${index===0?'selected':''}" data-bw-region="${index===0?'all':name}">${name}</button>`).join('');const render=()=>{const q=bwSearch.value.toLowerCase().trim(),rows=botswanaRegions.filter(x=>(bwRegion==='all'||x.region===bwRegion)&&(!q||`${x.region} ${x.area} ${x.experiences} ${x.properties.join(' ')}`.toLowerCase().includes(q)));bwResults.innerHTML=rows.length?rows.map(x=>`<article class="bw-card"><header><h3>${x.region}</h3><span>${x.properties.length} records</span></header><h4>Areas and reserves</h4><p>${x.area}</p><h4>Experiences</h4><p>${x.experiences}</p><h4>Lodges, camps and access points</h4><div class="property-list">${x.properties.map(p=>`<span>${p}</span>`).join('')}</div></article>`).join(''):'<div class="bw-empty">No Botswana place matches that search. Clear the search or choose All regions.</div>'};bwTabs.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;bwRegion=button.dataset.bwRegion;bwTabs.querySelectorAll('button').forEach(item=>item.classList.toggle('selected',item===button));render()});bwSearch.addEventListener('input',render);render()};
